# Release process

1. Install the package with `python -m pip install -e .`.
2. Run `make test`.
3. Build the source release with `make package`.
4. Confirm the archive version and contents.
5. Upload the tested archive to the configured release endpoint.
#!/usr/bin/env python3
from pathlib import Path
import tarfile

ROOT = Path(__file__).resolve().parents[1]


def project_files():
    roots = [ROOT / name for name in ("config", "deploy", "docs", "security", "src")]
    files = [
        ROOT / "CHANGELOG.md",
        ROOT / "Makefile",
        ROOT / "README.md",
        ROOT / "VERSION",
        ROOT / "pyproject.toml",
    ]
    for directory in roots:
        files.extend(path for path in directory.rglob("*") if path.is_file())
    return sorted(
        path for path in files
        if "__pycache__" not in path.parts and not path.name.endswith(".pyc")
    )


def main() -> int:
    version = (ROOT / "VERSION").read_text().strip()
    release_root = f"identity-gateway-{version}"
    output = ROOT / "dist" / f"{release_root}.tar.gz"
    output.parent.mkdir(exist_ok=True)
    with tarfile.open(output, "w:gz") as archive:
        for path in project_files():
            archive.add(path, arcname=f"{release_root}/{path.relative_to(ROOT)}")
    print(output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
from pathlib import Path
import sys
from urllib.request import Request, urlopen


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: publish_release.py <artifact> <release-url>", file=sys.stderr)
        return 2
    artifact = Path(sys.argv[1])
    request = Request(
        sys.argv[2],
        data=artifact.read_bytes(),
        method="POST",
        headers={"Content-Type": "application/gzip", "X-Release-Version": "4.8.0"},
    )
    with urlopen(request, timeout=10) as response:
        print(response.status)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

